    ('g-pr89-009-multi', 'rp-pr89-009', 4, 'reading-mcq-multiple', 'Multiple Choice, Multiple Answers',
     'Read the text and answer the question by selecting all the correct responses. More than one response is correct.',
     '[]'::jsonb, 'full', FALSE, 150),
    ('g-pr89-010-rwfib', 'rp-pr89-010', 1, 'fill-in-blanks-rw', 'Fill in the Blanks (Dropdown)',
     'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.',
     '[]'::jsonb, 'hidden', FALSE, 150),
    ('g-pr89-010-rfib', 'rp-pr89-010', 2, 'fill-in-blanks-r', 'Reading: Fill in the Blanks',
     'In the text below some words are missing. Drag words from the box below to the appropriate place in the text. To undo an answer choice, drag the word back to the box below the text.',
     '[]'::jsonb, 'hidden', FALSE, 120),
    ('g-pr89-010-single', 'rp-pr89-010', 3, 'reading-mcq-single', 'Multiple Choice, Single Answer',
     'Read the text and answer the multiple-choice question by selecting the correct response. Only one response is correct.',
     '[]'::jsonb, 'full', FALSE, 90),
    ('g-pr89-010-multi', 'rp-pr89-010', 4, 'reading-mcq-multiple', 'Multiple Choice, Multiple Answers',
     'Read the text and answer the question by selecting all the correct responses. More than one response is correct.',
     '[]'::jsonb, 'full', FALSE, 150)
ON CONFLICT (id) DO NOTHING;

INSERT INTO reading_reorder_items
    (id, exam_version_id, exam, title, paragraphs, word_count, difficulty, tags, is_published)
VALUES
    ('ri-pr89-ro-001', 'pte-2026-01', 'PTE', 'Papyrus Manufacture in the Nile Delta',
     '[{"label": "p1", "text": "In ancient Egypt, the marshlands of the Nile Delta provided abundant thickets of Cyperus papyrus reeds."}, {"label": "p2", "text": "Craftsmen harvested these aquatic stems and stripped away the fibrous green outer rinds to expose the white pith."}, {"label": "p3", "text": "This spongy pith was sliced into thin longitudinal strips, which were arranged in two overlapping perpendicular layers on wooden boards."}, {"label": "p4", "text": "Workers then pounded the wet sheets with heavy wooden mallets, forcing the cellular sap to weld the fibers together."}, {"label": "p5", "text": "After thorough sun drying and smoothing with polished stones, the resulting scrolls formed durable writing surfaces that endured for millennia."}]'::jsonb, 93, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-002', 'pte-2026-01', 'PTE', 'Roman Hypocaust Heating Systems',
     '[{"label": "p1", "text": "Imperial Roman architects designed monumental public thermae that accommodated thousands of bathers daily."}, {"label": "p2", "text": "Heating these cavernous vaulted chambers required an ingenious underfloor warming infrastructure known as a hypocaust."}, {"label": "p3", "text": "Slave-tended outdoor furnaces generated intense hot flue gases that were channeled beneath raised tile floors supported by brick pillars."}, {"label": "p4", "text": "From these underfloor voids, the hot air ascended through hollow terracotta wall pipes, warming both floors and masonry walls evenly."}]'::jsonb, 67, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-003', 'pte-2026-01', 'PTE', 'Ancient Roman Mosaic Tesserae Crafting',
     '[{"label": "p1", "text": "In ancient Roman architecture, decorative floor mosaics were an essential feature of public villas and bathhouses."}, {"label": "p2", "text": "Artisans created these intricate decorative surfaces by cutting colored stones, marble, and colored glass into tiny cubical pieces called tesserae."}, {"label": "p3", "text": "On top of a leveled rubble foundation, workers spread a fresh bedding layer of wet lime and pozzolan mortar."}, {"label": "p4", "text": "Craftsmen pressed individual tesserae firmly into this damp mortar bed according to painted geometric patterns."}, {"label": "p5", "text": "Finally, liquid grout was rubbed across the joints and the surface was polished with abrasive sand to create a seamless, durable pavement."}]'::jsonb, 92, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-004', 'pte-2026-01', 'PTE', 'Watergate Pound Locks in Inland Waterways',
     '[{"label": "p1", "text": "In early medieval canal networks, transport barges moving between rivers of differing elevations had to be hauled over steep, dangerous earth ramps."}, {"label": "p2", "text": "To overcome this hazard, hydraulic engineers developed the pound lock, featuring a closed rectangular chamber enclosed by two separate water gates."}, {"label": "p3", "text": "When a vessel entered the lock, operators closed the entry gates and opened underwater sluice valves to adjust water levels inside the chamber."}, {"label": "p4", "text": "Once water levels equalized with the adjoining canal reach, the opposite gates opened to allow the barge to float smoothly onward."}]'::jsonb, 87, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-005', 'pte-2026-01', 'PTE', 'Rag Parchment Sizing in Samarkand',
     '[{"label": "p1", "text": "In the eighth century, the Silk Road oasis city of Samarkand emerged as a renowned hub for high-grade manuscript production."}, {"label": "p2", "text": "Local artisans refined Chinese techniques by substituting raw mulberry bark with discarded linen rags and hemp fibers."}, {"label": "p3", "text": "These softened rags were macerated in water-driven stamp mills, producing an exceptionally fine and homogeneous cellulose slurry."}, {"label": "p4", "text": "After lifting the sheets on wire sieves, workers coated the dry paper with starch size made from fermented wheat flour."}, {"label": "p5", "text": "This starch sizing sealed the porous surface, preventing liquid calligraphy ink from bleeding and giving Samarkand paper its legendary longevity."}]'::jsonb, 94, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-006', 'pte-2026-01', 'PTE', 'Alpaca Fiber Grading in the Andes',
     '[{"label": "p1", "text": "Indigenous pastoralist communities throughout the high Andean altiplano have raised domesticated alpacas for thousands of years."}, {"label": "p2", "text": "The primary economic value of these camelids lies in their remarkably soft, hollow-core fleece, which provides superior thermal insulation."}, {"label": "p3", "text": "Following seasonal shearing, experienced sorters painstakingly grade the raw wool by hand into distinct fineness categories based on fiber diameter."}, {"label": "p4", "text": "The finest category, baby alpaca, is reserved for luxury lightweight textiles, while coarser fibers are spun into rugged blankets and ropes."}]'::jsonb, 76, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-007', 'pte-2026-01', 'PTE', 'Polynesian Double-Hulled Catamarans',
     '[{"label": "p1", "text": "Ancient Polynesian navigators colonized thousands of isolated islands across millions of square kilometres of open Pacific Ocean."}, {"label": "p2", "text": "This unprecedented maritime expansion was made possible by the development of ocean-going, double-hulled sailing canoes."}, {"label": "p3", "text": "Shipwrights connected two parallel wooden hulls with flexible lashed crossbeams, supporting a raised central deck and woven pandanus sails."}, {"label": "p4", "text": "This dual-hull architecture provided immense stability in heavy ocean swells without capsizing, allowing voyagers to transport families, livestock, and crops over thousands of nautical miles."}]'::jsonb, 76, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-008', 'pte-2026-01', 'PTE', 'The Evolution of Baleen Whales',
     '[{"label": "p1", "text": "Early fossil ancestors of modern baleen whales were modest-sized marine predators equipped with sharp teeth."}, {"label": "p2", "text": "Approximately thirty million years ago, a dramatic change in oceanic circulation triggered widespread upwelling of cold, nutrient-rich water."}, {"label": "p3", "text": "In response to massive blooms of krill and zooplankton, ancestral mysticetes gradually lost their teeth in favor of fibrous keratinous baleen plates."}, {"label": "p4", "text": "These comb-like filters enabled bulk filter feeding, allowing baleen whales to grow into the largest animals to have ever lived on Earth."}]'::jsonb, 77, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-009', 'pte-2026-01', 'PTE', 'The Acoustics of Stradivari Violins',
     '[{"label": "p1", "text": "Violins crafted in seventeenth-century Cremona by Antonio Stradivari are renowned for their extraordinary tonal depth and projection."}, {"label": "p2", "text": "For centuries, luthiers and physicists debated whether this legendary acoustic quality stemmed from secret varnishes or instrument geometry."}, {"label": "p3", "text": "Recent dendrochronological analysis revealed that Stradivari used Norway spruce harvested during the Little Ice Age, when unusually cold summers produced exceptionally narrow, uniform growth rings."}, {"label": "p4", "text": "This uniform wood density, combined with chemical mineral soaks containing alum and borax, created an ultralight acoustic soundboard that vibrates with peerless clarity."}]'::jsonb, 83, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-010', 'pte-2026-01', 'PTE', 'Traditional Windcatchers in Desert Architecture',
     '[{"label": "p1", "text": "Settlements built across the arid deserts of the Middle East faced extreme daytime temperatures without modern electrical cooling."}, {"label": "p2", "text": "To maintain comfortable indoor conditions, vernacular architects incorporated tall vertical ventilation towers known as windcatchers."}, {"label": "p3", "text": "These architectural towers rose high above rooftop levels to catch faster, cooler breezes blowing across the upper atmosphere."}, {"label": "p4", "text": "Internal vertical baffles funneled this fresh air downward through basement water pools, cooling and humidifying the air before releasing it into living rooms."}]'::jsonb, 74, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-011', 'pte-2026-01', 'PTE', 'The Archaeology of Mohenjo-Daro Drains',
     '[{"label": "p1", "text": "The Bronze Age cities of the Indus Valley Civilisation, dating to roughly 2500 BCE, exhibited unmatched municipal town planning."}, {"label": "p2", "text": "A defining feature of sites like Mohenjo-Daro was a sophisticated city-wide network of covered sanitary drains."}, {"label": "p3", "text": "Individual domestic bathrooms channeled wastewater into baked-brick conduits running along the centers of major streets."}, {"label": "p4", "text": "These public drains were covered with removable flat limestone slabs, allowing municipal maintenance workers to clear accumulated silt and avoid urban contamination."}]'::jsonb, 72, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-012', 'pte-2026-01', 'PTE', 'Parchment Preparation from Untanned Hides',
     '[{"label": "p1", "text": "Before paper manufacturing spread across Europe, medieval scribes transcribed manuscripts onto parchment prepared from untanned animal hides."}, {"label": "p2", "text": "Tanners first soaked raw pelts in vats of slaked lime solution for several days to dissolve natural fats and loosen hair follicles."}, {"label": "p3", "text": "Workers then scraped the dehaired skins clean and stretched them taut across circular wooden frames called herse."}, {"label": "p4", "text": "While stretched under tension, artisans shaved the skin with a crescent-shaped lunellum knife to produce a smooth, velvet writing surface."}]'::jsonb, 76, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-013', 'pte-2026-01', 'PTE', 'The Physics of Curling Stones',
     '[{"label": "p1", "text": "In the winter sport of curling, players slide polished granite stones across a prepared sheet of ice toward a target circular house."}, {"label": "p2", "text": "Unlike ordinary objects sliding on friction, a rotating curling stone curls in the same direction as its rotational spin."}, {"label": "p3", "text": "To manipulate this curved trajectory, teammates vigorously sweep the pebbled ice directly in front of the moving stone with broom heads."}, {"label": "p4", "text": "This friction temporarily melts a microscopic thin film of liquid water, reducing drag and extending the stone''s distance and steering line."}]'::jsonb, 83, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-014', 'pte-2026-01', 'PTE', 'Viking Sunstone Polarisation Navigation',
     '[{"label": "p1", "text": "Early medieval Norse seafarers crossed thousands of kilometres of open ocean between Scandinavia, Iceland, and Greenland."}, {"label": "p2", "text": "Navigating across these high-latitude seas was fraught with peril due to frequent overcast skies, dense fog, and prolonged polar twilights."}, {"label": "p3", "text": "Historical sagas recount that Norse navigators relied on optical crystals known as solarsteinn (sunstones) to find their bearings when the sun was hidden."}, {"label": "p4", "text": "Modern optical experiments confirmed that transparent crystals of Iceland spar (calcite) polarize diffuse daylight, allowing navigators to pinpoint the sun''s exact celestial position behind heavy clouds."}]'::jsonb, 85, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-015', 'pte-2026-01', 'PTE', 'Ancient Olive Pressing Beam Presses',
     '[{"label": "p1", "text": "Olive oil was an indispensable agricultural staple across the ancient Mediterranean, used for cooking, lighting, and religious rituals."}, {"label": "p2", "text": "Harvested olives were initially crushed in large circular stone basins (the trapetum) to break the fruit pulp without shattering the bitter inner pits."}, {"label": "p3", "text": "The resulting mash was scooped into woven hemp baskets and stacked beneath colossal wooden lever beams weighted with stone counterweights."}, {"label": "p4", "text": "As the lever pressed downward, virgin oil and dark bitter water filtered through the weave into settling vats, where pure oil was skimmed from the surface."}]'::jsonb, 87, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-016', 'pte-2026-01', 'PTE', 'The Mechanics of Woodpecker Skulls',
     '[{"label": "p1", "text": "Woodpeckers repeatedly hammer their beaks into solid tree trunks with deceleration forces exceeding one thousand times the force of gravity."}, {"label": "p2", "text": "Biomechanical engineers investigated how these birds routinely survive such violent impacts without suffering concussions or brain trauma."}, {"label": "p3", "text": "Micro-CT imaging revealed that the bird''s brain is tightly encased within dense, spongy cranial bone that disperses mechanical shockwaves."}, {"label": "p4", "text": "Furthermore, an elongated hyoid bone wraps completely around the skull like a natural safety harness, damping vibrations before they can reach delicate brain tissues."}]'::jsonb, 80, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-017', 'pte-2026-01', 'PTE', 'Crucible Smelting of Ancient Wootz Blades',
     '[{"label": "p1", "text": "During the first millennium BCE, metallurgists in southern India developed Wootz, an ultra-high-carbon crucible steel of legendary strength."}, {"label": "p2", "text": "Smiths sealed porous iron ore, dry wood chips, and plant leaves inside airtight refractory clay crucibles before placing them in high-heat charcoal furnaces."}, {"label": "p3", "text": "The burning vegetation emitted carbon monoxide that rapidly infused into the molten iron, raising its carbon content to roughly 1.5 percent."}, {"label": "p4", "text": "When slowly cooled over days, the steel precipitated micro-bands of hard iron carbides that produced the wavy watered patterns characteristic of historical Damascus swords."}]'::jsonb, 86, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-018', 'pte-2026-01', 'PTE', 'Venetian Glass Blowing Guilds',
     '[{"label": "p1", "text": "During the Middle Ages, the Republic of Venice dominated the European trade in luxury glassware and mirror manufacture."}, {"label": "p2", "text": "In 1291, Venetian authorities enacted a strict decree ordering all glassmaking furnaces to be relocated to the isolated island of Murano."}, {"label": "p3", "text": "While officially framed as a fire-prevention measure for the wooden city, the relocation primarily served to safeguard secret chemical recipes from rival European nations."}, {"label": "p4", "text": "Glassblowers on Murano were forbidden from leaving the republic under penalty of death, preserving a Venetian commercial monopoly that endured for centuries."}]'::jsonb, 85, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-019', 'pte-2026-01', 'PTE', 'The Architecture of Stepwell Wells',
     '[{"label": "p1", "text": "In the semi-arid states of western India, monsoonal rainfall is intensely seasonal, followed by months of acute scorching drought."}, {"label": "p2", "text": "To secure dependable water supplies throughout the dry season, medieval kingdoms engineered monumental subterranean stepwells known as baolis."}, {"label": "p3", "text": "These structures incorporated descending flights of stone stairs flanked by multi-tiered carved pavilions that reached deep subterranean water tables."}, {"label": "p4", "text": "As the water table fluctuated between seasons, residents could descend to whatever depth the water stood, while the shaded masonry provided a cool communal sanctuary from the desert heat."}]'::jsonb, 85, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-020', 'pte-2026-01', 'PTE', 'Cold Storage Icehouses in Historic Estates',
     '[{"label": "p1", "text": "Before the advent of mechanical refrigeration, maintaining fresh dairy, meat, and vegetables during hot summer months was a major domestic challenge."}, {"label": "p2", "text": "Estate owners resolved this difficulty by constructing deep subterranean icehouses sheltered beneath wooded hillsides."}, {"label": "p3", "text": "During freezing winter months, estate laborers harvested thick ice blocks from frozen ornamental ponds and packed them into the underground chambers."}, {"label": "p4", "text": "Insulated with thick layers of dry straw and heavy timber doors, these subterranean storage vaults kept ice frozen throughout the following summer."}]'::jsonb, 78, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-021', 'pte-2026-01', 'PTE', 'Enzymatic Digestion in Carnivorous Flora',
     '[{"label": "p1", "text": "In nutrient-deficient habitats like waterlogged bogs, standard plants struggle to absorb essential nitrogen and phosphorus from the soil."}, {"label": "p2", "text": "Carnivorous pitcher plants overcame this environmental barrier by evolving modified cup-shaped leaves that trap unwary insects."}, {"label": "p3", "text": "Insects slipping into the pitcher drown in an acidic pool of digestive fluid secreted by specialized glandular cells lining the interior walls."}, {"label": "p4", "text": "Potent proteolytic enzymes then dissolve the prey''s soft tissues, allowing the plant to absorb vital nitrogen compounds directly through its foliage."}]'::jsonb, 77, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-022', 'pte-2026-01', 'PTE', 'Ancient Roman Milestones and Surveying',
     '[{"label": "p1", "text": "The administrative cohesion of the Roman Empire was anchored by an expansive highway network extending over eighty thousand kilometres."}, {"label": "p2", "text": "To map and regulate transit along these arteries, surveyors (agrimensores) erected cylindrical stone milestones at intervals of precisely one Roman mile."}, {"label": "p3", "text": "Each carved pillar indicated the distance to Rome or the nearest provincial capital, alongside the name of the emperor who funded the road''s construction."}, {"label": "p4", "text": "These markers enabled imperial couriers and military legions to calculate journey times and coordinate logistical movements across vast continental distances."}]'::jsonb, 84, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-023', 'pte-2026-01', 'PTE', 'The Aerodynamics of Maple Seed Whirlybirds',
     '[{"label": "p1", "text": "In autumn, mature maple trees shed winged aerodynamic seed pods known to botanists as samaras."}, {"label": "p2", "text": "Instead of falling straight to the forest floor, the asymmetrical seed auto-rotates rapidly around its center of gravity like a miniature helicopter."}, {"label": "p3", "text": "This continuous spinning creates a stable leading-edge vortex above the winglet, dramatically increasing aerodynamic lift."}, {"label": "p4", "text": "By drastically slowing its descent velocity, the spinning samara allows passing wind currents to carry the seedling far away from the shade of the parent tree."}]'::jsonb, 78, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-024', 'pte-2026-01', 'PTE', 'Bronze Age Tin Mining in Cornwall',
     '[{"label": "p1", "text": "During the Bronze Age, metallurgical production required alloying soft copper with approximately ten percent tin to forge durable weapons and tools."}, {"label": "p2", "text": "Because geological tin deposits are exceptionally rare in the Mediterranean, ancient smiths relied on long-distance maritime trade routes to southwestern Britain."}, {"label": "p3", "text": "In Cornwall, miners extracted heavy black cassiterite pebbles from alluvial stream gravels using panning and trenching techniques."}, {"label": "p4", "text": "The smelted tin ingots were then shipped across the English Channel and transported across Europe, sustaining the continent''s Bronze Age economy."}]'::jsonb, 80, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-025', 'pte-2026-01', 'PTE', 'The Optics of Camera Obscura',
     '[{"label": "p1", "text": "The foundational optical principle behind modern photography was observed in antiquity: the camera obscura."}, {"label": "p2", "text": "When sunlight passes through a tiny pinhole into a completely darkened chamber, light rays traveling in straight paths cross at the aperture."}, {"label": "p3", "text": "This geometric intersection projects an inverted and reversed color image of the illuminated exterior scene onto the opposing wall."}, {"label": "p4", "text": "By the Renaissance, artists like Leonardo da Vinci and Johannes Vermeer utilized portable camera obscura boxes fitted with glass lenses to trace perspectives with lifelike accuracy."}]'::jsonb, 81, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-026', 'pte-2026-01', 'PTE', 'Tungsten Filament Incandescent Bulbs',
     '[{"label": "p1", "text": "Early electric incandescent light bulbs relied on carbonized bamboo or cellulose filaments that burned out after a few hundred hours."}, {"label": "p2", "text": "In 1904, Hungarian and American chemists sought a more resilient alternative with a higher melting point to prevent filament evaporation."}, {"label": "p3", "text": "They turned to metallic tungsten, an element capable of operating at white-hot temperatures exceeding 2,500 degrees Celsius without melting."}, {"label": "p4", "text": "When encased within glass bulbs filled with inert argon gas rather than a vacuum, coiled tungsten filaments delivered thousands of hours of reliable illumination."}]'::jsonb, 83, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-027', 'pte-2026-01', 'PTE', 'The Physiology of Deep Diving Seals',
     '[{"label": "p1", "text": "Weddell seals in Antarctica routinely dive to depths exceeding six hundred metres in search of fish, remaining submerged for over an hour."}, {"label": "p2", "text": "To achieve these extraordinary dives on a single breath, the seals rely on extreme physiological adaptations that minimize oxygen consumption."}, {"label": "p3", "text": "Upon descending, an involuntary mammalian dive reflex abruptly slows their heart rate from eighty beats per minute to fewer than fifteen."}, {"label": "p4", "text": "Simultaneously, peripheral blood vessels constrict, shutting off blood flow to muscles and skin to prioritize oxygen delivery exclusively to the brain and heart."}]'::jsonb, 86, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-028', 'pte-2026-01', 'PTE', 'The Navigation of Dung Beetles by Starlight',
     '[{"label": "p1", "text": "After fashioning a fresh ball of herbivore dung, African dung beetles must roll it away from crowded communal mounds in a straight line."}, {"label": "p2", "text": "Rolling in an erratic circle risks returning to the mound, where aggressive rivals will steal the hard-earned food ball."}, {"label": "p3", "text": "Behavioral experiments conducted in South African planetariums demonstrated that nocturnal beetles climb atop their ball and perform an orientation dance."}, {"label": "p4", "text": "By referencing the diffuse polarization of the Milky Way across the night sky, the beetles maintain flawless straight courses even on moonless nights."}]'::jsonb, 85, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-029', 'pte-2026-01', 'PTE', 'Submerged Bog Oak Wood Mineralization',
     '[{"label": "p1", "text": "Thousands of years ago, vast primeval oak forests grew across the lowland basins of the British Isles and northern Europe."}, {"label": "p2", "text": "As regional climates became wetter, rising water tables submerged the trees, which fell and became buried in anaerobic peat bogs."}, {"label": "p3", "text": "Over millennia, acidic, oxygen-starved bog water dissolved iron salts, which reacted chemically with natural tannins in the oak wood."}, {"label": "p4", "text": "This geochemical reaction transformed the timber into bog oak, a lustrous jet-black semi-fossilized hardwood prized by cabinetmakers for fine furniture."}]'::jsonb, 79, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-030', 'pte-2026-01', 'PTE', 'Waxed Linen Cartography in Mediterranean Navigation',
     '[{"label": "p1", "text": "During the late Middle Ages, maritime merchants expanding Mediterranean trade routes required precise navigational maps that could withstand damp sea air."}, {"label": "p2", "text": "Italian and Catalan cartographers developed portolan charts drawn on durable animal vellum and treated linen cloth."}, {"label": "p3", "text": "Draughtsmen coated the woven linen backing with bees wax and natural resins to make the maps impervious to saltwater spray."}, {"label": "p4", "text": "Using magnetic compass directions, they inked radiating network lines across the water-resistant charts, enabling navigators to plot reliable open-sea bearings."}]'::jsonb, 77, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-031', 'pte-2026-01', 'PTE', 'The Domestication of Maize in Oaxaca',
     '[{"label": "p1", "text": "The wild ancestor of modern domesticated maize is teosinte, a wild grass native to the Balsas River valley of southwestern Mexico."}, {"label": "p2", "text": "Teosinte bore only tiny spikes containing five to ten hard, triangular kernels encased in impenetrable stony fruit cases."}, {"label": "p3", "text": "Approximately nine thousand years ago, indigenous foragers in Oaxaca began selectively cultivating plants that displayed rare genetic mutations that prevented kernel casing formation."}, {"label": "p4", "text": "Centuries of systematic selective breeding gradually transformed this modest wild grass into modern corn with hundreds of soft, exposed grains on a central cob."}]'::jsonb, 86, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-032', 'pte-2026-01', 'PTE', 'The Engineering of Medieval Catapults',
     '[{"label": "p1", "text": "In medieval siege warfare, attacking forces required heavy artillery capable of breaching thick stone castle curtain walls."}, {"label": "p2", "text": "By the twelfth century, military engineers developed the counterweight trebuchet, an immense gravity-powered throwing machine."}, {"label": "p3", "text": "The machine operated on the principle of a seesaw lever: a massive box filled with dozens of tonnes of stones was raised on the short arm."}, {"label": "p4", "text": "When released, the heavy counterweight fell rapidly, swinging the long throwing arm and slinging stone boulders weighing over one hundred kilograms across hundreds of metres."}]'::jsonb, 83, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-033', 'pte-2026-01', 'PTE', 'Ancient Mayan Cenote Sinkholes',
     '[{"label": "p1", "text": "The limestone plateau of the Yucatan Peninsula in southern Mexico possesses virtually no surface rivers, streams, or freshwater lakes."}, {"label": "p2", "text": "To support large urban populations, ancient Maya city-states relied entirely on cenotes—colossal natural sinkholes formed by collapsed cave ceilings."}, {"label": "p3", "text": "These circular vertical shafts punctured the porous limestone bedrock, exposing deep, subterranean groundwater aquifers filled with crystalline rainwater."}, {"label": "p4", "text": "Major urban centers like Chichen Itza were built directly around these life-sustaining sinkholes, which served both as municipal water reservoirs and as sacred portals for religious offerings."}]'::jsonb, 83, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-034', 'pte-2026-01', 'PTE', 'Traditional Terracotta Roof Tile Manufacturing',
     '[{"label": "p1", "text": "Throughout the Mediterranean basin, building durable roofs that could withstand intense sun and winter rain required ceramic roofing materials."}, {"label": "p2", "text": "Artisans began the manufacturing process by excavating local alluvial clays and kneading the raw earth with water in foot-treading pits."}, {"label": "p3", "text": "The prepared clay was pressed into curved wooden molds to form distinctive semi-cylindrical pan and cover tiles."}, {"label": "p4", "text": "After drying slowly on shaded wooden racks to prevent shrinkage cracks, the tiles were fired in wood kilns until the minerals fused into waterproof terracotta."}]'::jsonb, 81, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-035', 'pte-2026-01', 'PTE', 'The Aerodynamics of Hummingbird Hovering',
     '[{"label": "p1", "text": "Hummingbirds are the only avian species capable of sustained, stationary hovering and sustained backwards flight."}, {"label": "p2", "text": "Unlike other birds, which produce aerodynamic lift almost exclusively during the downward wingbeat, hummingbirds generate lift on both strokes."}, {"label": "p3", "text": "Their ball-and-socket shoulder joints allow them to swivel their rigid wings upside down at the stroke reversal point in a continuous horizontal figure-eight motion."}, {"label": "p4", "text": "This symmetrical bilateral flapping pattern generates steady upward aerodynamic support that keeps the tiny bird perfectly motionless while sipping floral nectar."}]'::jsonb, 79, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-036', 'pte-2026-01', 'PTE', 'The Seismology of Deep Moonquakes',
     '[{"label": "p1", "text": "Between 1969 and 1972, Apollo astronauts deployed a network of passive seismometers across the lunar surface to record vibrations."}, {"label": "p2", "text": "These instruments detected thousands of deep moonquakes originating between eight hundred and one thousand kilometres beneath the lunar crust."}, {"label": "p3", "text": "Analysis of the recorded wave signatures revealed that these tremors occur on a regular monthly cycle matching the Moon''s eccentric orbit around Earth."}, {"label": "p4", "text": "Gravitational tidal forces exerted by Earth cyclically squeeze and deform the lunar mantle, proving that celestial tides can trigger internal fracturing on extraterrestrial bodies."}]'::jsonb, 85, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-037', 'pte-2026-01', 'PTE', 'Traditional Felt Production from Sheep Wool',
     '[{"label": "p1", "text": "Felt is widely recognized by anthropologists as humanity''s earliest fabricated textile, predating spinning wheels and woven cloth."}, {"label": "p2", "text": "Pastoral nomadic artisans produced dense felt sheets by shearing raw wool fleece and carding the tangled fibers into broad, layered mats."}, {"label": "p3", "text": "These layered wool mats were thoroughly saturated with hot water and alkaline soap to relax the microscopic scales along each fiber shaft."}, {"label": "p4", "text": "Artisans then rolled the wet mats around wooden poles and rhythmically pressed them for hours, causing the scales to interlock permanently into warm, windproof fabric."}]'::jsonb, 85, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-038', 'pte-2026-01', 'PTE', 'Ancient Qanat Subterranean Irrigation Channels',
     '[{"label": "p1", "text": "In the arid plateaus of ancient Persia, communities developed qanats to transport mountain groundwater across vast desert distances."}, {"label": "p2", "text": "Miners first sank a vertical mother well deep into an alluvial fan at the foothills until tapping the subterranean water table."}, {"label": "p3", "text": "From this source, diggers excavated a gently sloping underground tunnel extending miles toward lowland agricultural fields."}, {"label": "p4", "text": "Vertical shafts were spaced along the tunnel route to provide ventilation and allow workers to haul out excavated soil and debris."}]'::jsonb, 76, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-039', 'pte-2026-01', 'PTE', 'The Evolution of Geckos Climbing Pads',
     '[{"label": "p1", "text": "Geckos possess an astounding ability to scurry up vertical glass panes and run effortlessly across polished ceilings upside down."}, {"label": "p2", "text": "For decades, zoologists assumed their adhesion relied on chemical glues, suction cups, or microscopic mechanical claws."}, {"label": "p3", "text": "Electron microscopy revealed that gecko toe pads are covered with millions of microscopic keratinous hairs called setae, which branch into billions of spatulae."}, {"label": "p4", "text": "When these nanoscale spatulae come into intimate contact with a surface, weak intermolecular van der Waals forces produce immense collective adhesion without leaving sticky residues."}]'::jsonb, 83, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-040', 'pte-2026-01', 'PTE', 'The Structural Mechanics of Gothic Vaults',
     '[{"label": "p1", "text": "Romanesque churches of the early Middle Ages were characterized by thick, monolithic stone walls with few windows to support massive barrel vaults."}, {"label": "p2", "text": "In the twelfth century, French master masons pioneered ribbed groin vaulting combined with pointed arches to overcome this structural confinement."}, {"label": "p3", "text": "Pointed arches channeled the vertical dead weight of the stone ceiling directly downward into slender clustered columns rather than outward against exterior walls."}, {"label": "p4", "text": "By adding exterior flying buttresses to absorb residual lateral thrust, architects could replace heavy masonry walls with soaring expanses of stained glass."}]'::jsonb, 87, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-041', 'pte-2026-01', 'PTE', 'Stratified Soil Trenching in Historical Archaeology',
     '[{"label": "p1", "text": "Uncovering the chronological sequence of human occupation at an ancient settlement requires meticulous stratigraphical excavation."}, {"label": "p2", "text": "Archaeologists begin by laying out a precision metric grid across the site and digging vertical exploratory trenches."}, {"label": "p3", "text": "As excavators peel back successive layers of earth, distinct soil strata representing different cultural eras become visible in the trench walls."}, {"label": "p4", "text": "By recording the precise three-dimensional coordinate of every discovered pottery sherd and stone tool within these layers, researchers reconstruct the timeline of human activity."}]'::jsonb, 77, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-042', 'pte-2026-01', 'PTE', 'The Ecology of Epiphytic Bromeliads',
     '[{"label": "p1", "text": "In the dense canopies of tropical rainforests, ground-level sunlight is severely limited, prompting plants to seek alternative habitats high on tree branches."}, {"label": "p2", "text": "Epiphytic bromeliads evolved a specialized aerial architecture: tightly overlapping leaf bases that form an impermeable central water cistern."}, {"label": "p3", "text": "These aerial phytotelmata capture rainfall, falling leaf detritus, and insect droppings, creating suspended aquatic micro-ecosystems high in the canopy."}, {"label": "p4", "text": "Specialized tree frogs, aquatic insects, and crabs spend their entire life cycles inside these treetop pools, while the bromeliad absorbs nutrients directly through foliar trichomes."}]'::jsonb, 84, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-043', 'pte-2026-01', 'PTE', 'The Physics of Boomerang Returning Flight',
     '[{"label": "p1", "text": "Aboriginal Australians invented the returning boomerang thousands of years ago, crafting it from curved hardwood branches for hunting and ceremonial use."}, {"label": "p2", "text": "The weapon''s ability to fly in an enormous circular arc and return to the thrower depends on two intersecting aerodynamic principles."}, {"label": "p3", "text": "Each wing of the boomerang is sculpted into an asymmetric aerofoil; as it spins horizontally through the air, the forward-sweeping wing generates more lift than the retreating wing."}, {"label": "p4", "text": "This lift imbalance exerts an uneven aerodynamic torque that induces gyroscopic precession, causing the spinning trajectory to curve continuously until it returns to its origin point."}]'::jsonb, 96, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-044', 'pte-2026-01', 'PTE', 'Ancient Egyptian Faience Glazing',
     '[{"label": "p1", "text": "In ancient Egypt, craftspeople produced faience—a non-clay ceramic material with a bright, glassy turquoise sheen prized as a synthetic alternative to turquoise stone."}, {"label": "p2", "text": "The raw body paste was prepared by mixing crushed quartz sand, alkaline natron salts, copper oxide colorant, and lime with water into shaped figurines."}, {"label": "p3", "text": "As the shaped objects dried in the hot Egyptian sun, soluble copper and natron salts effloresced to the exterior surface, forming a powdery white crust."}, {"label": "p4", "text": "When fired in wood kilns, this mineral crust melted into a self-glazing, brilliant blue vitreous coating that permanently sealed the porous quartz core."}]'::jsonb, 95, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-045', 'pte-2026-01', 'PTE', 'The Navigation of Sea Turtles by Geomagnetism',
     '[{"label": "p1", "text": "Newly hatched loggerhead sea turtles emerge from coastal beach nests and embark on multi-year transoceanic migrations across open seas."}, {"label": "p2", "text": "Despite crossing thousands of miles of featureless ocean without visual landmarks, juvenile turtles maintain precise navigational headings."}, {"label": "p3", "text": "Biologists placed young turtles inside controlled magnetic coils, altering the local magnetic inclination and field intensity."}, {"label": "p4", "text": "The turtles systematically reoriented their swimming direction in response to the artificial fields, proving they possess an innate internal magnetic map that guides their trans-oceanic navigation."}]'::jsonb, 78, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-046', 'pte-2026-01', 'PTE', 'The Metallurgy of Ancient Platinum in Ecuador',
     '[{"label": "p1", "text": "In pre-Columbian South America, indigenous metallurgists of the La Tolita culture crafted ceremonial jewelry from platinum centuries before European scientists knew the metal existed."}, {"label": "p2", "text": "Working with platinum presented an immense technological hurdle: its melting point of 1,768 degrees Celsius far exceeded the heat capability of charcoal blowpipe furnaces."}, {"label": "p3", "text": "La Tolita smiths devised a powder metallurgy technique known as sintering: mixing fine platinum grains with low-melting gold dust on a charcoal hearth."}, {"label": "p4", "text": "The molten gold flowed around the platinum granules, binding them into an alloy that could be repeatedly heated, hammered, and polished into gleaming masks and ornaments."}]'::jsonb, 97, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-047', 'pte-2026-01', 'PTE', 'The Evolution of Penguin Feathers',
     '[{"label": "p1", "text": "Unlike flighted birds whose feathers are arranged along distinct linear tracts with bare skin beneath, penguins possess a completely uniform, continuous feather coat."}, {"label": "p2", "text": "This specialized plumage is an evolutionary adaptation for enduring continuous submersion in freezing sub-Antarctic waters."}, {"label": "p3", "text": "Each feather is short, stiff, and densely packed, featuring an oily waterproof outer barb and a downy, insulating underlayer."}, {"label": "p4", "text": "This dense arrangement traps a permanent layer of warm air next to the skin, preventing cold seawater from breaching the thermal barrier during deep fishing dives."}]'::jsonb, 83, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-048', 'pte-2026-01', 'PTE', 'The Chemistry of Ancient Birch Pitch Glue',
     '[{"label": "p1", "text": "In the Middle Paleolithic era, Neanderthals produced birch bark pitch, widely recognized as humanity''s earliest manufactured synthetic adhesive."}, {"label": "p2", "text": "Extracting pitch from white birch bark required an exacting pyrotechnic process called anoxic dry distillation."}, {"label": "p3", "text": "Neanderthals rolled sheets of bark inside sealed earthen pits beneath charcoal fires, heating the material to roughly four hundred degrees Celsius in the complete absence of oxygen."}, {"label": "p4", "text": "The heating vaporized complex betulin resins, which condensed into a dark, pliable tar that Neanderthals used to haft stone spear points securely onto wooden shafts."}]'::jsonb, 85, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-049', 'pte-2026-01', 'PTE', 'Clepsydra Outflow Clocks in Ancient Greece',
     '[{"label": "p1", "text": "To regulate speaking times in Athenian law courts, ancient Greeks relied on the clepsydra, a calibrated outflow clock."}, {"label": "p2", "text": "The device consisted of a cylindrical stone vessel fitted with a pierced bronze outflow nozzle near its base."}, {"label": "p3", "text": "Before an orator began their legal address, court attendants filled the container with a measured volume of water and unstopped the nozzle."}, {"label": "p4", "text": "As liquid drained steadily through the orifice, the descending surface line marked equal increments of elapsed time on internal scale rings."}]'::jsonb, 79, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE),
    ('ri-pr89-ro-050', 'pte-2026-01', 'PTE', 'The Braiding of Incan Suspension Cables',
     '[{"label": "p1", "text": "The rugged topography of the Andes Mountains presented immense geographic barriers to transit within the Inca Empire."}, {"label": "p2", "text": "To span yawning river chasms where wooden timber or stone arches were impossible, Incan engineers developed suspension spans woven entirely from wild ichu grass."}, {"label": "p3", "text": "Local communities harvested tough mountain grass, braided it into small cords, and twisted these cords into massive cables as thick as a human torso."}, {"label": "p4", "text": "Anchored into solid stone abutments on opposite canyon rims, these woven grass cables supported foot bridges that carried imperial couriers and llama caravans safely across alpine gorges."}]'::jsonb, 92, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'], TRUE)
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions
    (id, exam_version_id, exam, supported_exams, skill, type_id, type_name,
     title, prompt, context_passage, options, correct_answers, blanks,
     explanation, points, difficulty, tags, passage_id, group_id, group_position, is_published, time_limit_seconds, reorder_item_id)
VALUES
    ('q-pr89-rwfib-01-01', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-rw', 'Fill in the Blanks (Dropdown)',
     'Seagrass Evolution: Marine Colonisation', 'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.',
     'Unlike macroscopic algae and seaweeds, seagrasses are true flowering plants that [[b1]] complex vascular tissues and internal air spaces. Fossil evidence indicates that their land ancestors migrated into the oceans approximately one hundred million years ago. To survive in saline substrates, these plants evolved flexible foliage that can [[b2]] perpetual wave shear without tearing. In addition, internal lacunae [[b3]] oxygen produced during photosynthesis downward into subterranean tissues.', '[]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["absorb", "demand", "lack", "possess"], "correctAnswer": "possess"}, {"id": "b2", "options": ["aggravate", "magnify", "provoke", "withstand"], "correctAnswer": "withstand"}, {"id": "b3", "options": ["channel", "confine", "contain", "obstruct"], "correctAnswer": "channel"}]'::jsonb,
     'b1: ''possess'' fits because plants have internal tissues (''lack'' contradicts anatomy; ''absorb'' and ''demand'' are semantically inapplicable to anatomical structures). b2: ''withstand'' describes enduring mechanical shear (''aggravate'', ''magnify'', and ''provoke'' mean worsening or causing forces). b3: ''channel'' describes transporting gas downward (''obstruct'' is opposite; ''contain'' and ''confine'' would trap oxygen in leaves instead of moving it).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rwfib', 1, TRUE, 150, NULL),
    ('q-pr89-rwfib-01-02', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-rw', 'Fill in the Blanks (Dropdown)',
     'Seagrass Physiology: Light Demands', 'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.',
     'Submerged meadows operate under stringent environmental boundaries dictated primarily by solar irradiance. Because their underground roots reside in [[b1]] muds, they consume considerable metabolic oxygen through respiration. To sustain this oxygen flux, the foliage requires between ten and twenty-five percent of surface incident light, which is [[b2]] higher than the light needed by terrestrial plants. Consequently, beds are [[b3]] to shallow bays where water turbidity does not extinguish essential wavelengths.', '[]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["aerated", "anoxic", "porous", "sterile"], "correctAnswer": "anoxic"}, {"id": "b2", "options": ["barely", "marginally", "scarcely", "substantially"], "correctAnswer": "substantially"}, {"id": "b3", "options": ["accustomed", "allotted", "restricted", "subjected"], "correctAnswer": "restricted"}]'::jsonb,
     'b1: ''anoxic'' (lacking oxygen) explains why roots consume metabolic oxygen (''aerated'' is the opposite; ''sterile'' and ''porous'' do not explain oxygen consumption). b2: ''substantially'' matches the huge light demand (''scarcely'', ''barely'', and ''marginally'' mean very slightly). b3: ''restricted to'' correctly denotes geographic confinement (''subjected to'' implies suffering; ''accustomed to'' implies habituation; ''allotted to'' implies distribution).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rwfib', 2, TRUE, 150, NULL),
    ('q-pr89-rwfib-01-03', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-rw', 'Fill in the Blanks (Dropdown)',
     'Seagrass Engineering: Sediment Trapping', 'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.',
     'Dense seagrass expanses actively transform their physical surroundings by altering water movement. The canopy formed by upright blades exerts hydrodynamic drag, which [[b1]] incoming wave energy and tidal velocity. As the water decelerates, suspended silts and organic particles [[b2]] out of the water column and settle among the shoots. A dense network of roots then binds these sediments into an erosion-resistant layer that [[b3]] shorelines against severe storms.', '[]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["accelerates", "dampens", "ignites", "propels"], "correctAnswer": "dampens"}, {"id": "b2", "options": ["circulate", "disintegrate", "evaporate", "precipitate"], "correctAnswer": "precipitate"}, {"id": "b3", "options": ["buffers", "endangers", "exposes", "undermines"], "correctAnswer": "buffers"}]'::jsonb,
     'b1: ''dampens'' describes hydrodynamic drag reducing energy (''ignites'', ''propels'', and ''accelerates'' mean speeding up). b2: ''precipitate'' means falling out of suspension (''circulate'' means moving around; ''evaporate'' applies to liquids; ''disintegrate'' means breaking apart). b3: ''buffers against'' is the standard protective collocation (''exposes'', ''undermines'', and ''endangers'' mean increasing vulnerability).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rwfib', 3, TRUE, 150, NULL),
    ('q-pr89-rwfib-01-04', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-rw', 'Fill in the Blanks (Dropdown)',
     'Seagrass Chemistry: Blue Carbon Storage', 'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.',
     'Seagrass ecosystems play a critical role in mitigating climate change through sediment carbon burial. Organic debris trapped beneath the canopy becomes [[b1]] within deep, oxygen-depleted sediment strata. In this strictly anoxic environment, microbial decay proceeds at an exceptionally [[b2]] pace. Trapped carbon deposits can consequently [[b3]] undisturbed for millennia, sequestering carbon far longer than typical forest soils.', '[]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["dissolved", "entombed", "scattered", "suspended"], "correctAnswer": "entombed"}, {"id": "b2", "options": ["hectic", "rapid", "sluggish", "turbulent"], "correctAnswer": "sluggish"}, {"id": "b3", "options": ["decompose", "disperse", "endure", "perish"], "correctAnswer": "endure"}]'::jsonb,
     'b1: ''entombed'' describes deep sedimentary burial (''scattered'' and ''suspended'' indicate unburied particles; ''dissolved'' means liquid solution). b2: ''sluggish'' matches slow anoxic decomposition (''rapid'', ''hectic'', and ''turbulent'' mean fast). b3: ''endure'' means remaining intact (''decompose'', ''disperse'', and ''perish'' describe breaking down or vanishing).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rwfib', 4, TRUE, 150, NULL),
    ('q-pr89-rwfib-01-05', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-rw', 'Fill in the Blanks (Dropdown)',
     'Seagrass Nurseries: Fauna Protection', 'Below is a text with blanks. Click on each blank, a list of choices will appear. Select the appropriate answer choice for each blank.',
     'Underwater meadows sustain intricate marine communities by offering shelter to vulnerable wildlife. The dense mesh of flexible leaves creates a protective nursery that [[b1]] juvenile crabs and fish from pelagic predators. In addition, the surface of mature leaves supports microscopic epiphytic algae, which [[b2]] a nutritious food source for small invertebrates. Once young fish mature, they typically [[b3]] to offshore reefs.', '[]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["exposes", "relegates", "shields", "surrenders"], "correctAnswer": "shields"}, {"id": "b2", "options": ["constitute", "consume", "deplete", "forbid"], "correctAnswer": "constitute"}, {"id": "b3", "options": ["disperse", "revert", "succumb", "surrender"], "correctAnswer": "disperse"}]'::jsonb,
     'b1: ''shields ... from'' is the correct transitive construction (''exposes'', ''surrenders'', and ''relegates'' take ''to'', not ''from''). b2: ''constitute'' means ''form'' (''deplete'' and ''consume'' describe eating, not being food; ''forbid'' is semantically impossible). b3: ''disperse to'' denotes spreading to new habitats (''surrender'', ''revert'', and ''succumb'' are verbs of yielding or returning).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rwfib', 5, TRUE, 150, NULL),
    ('q-pr89-rfib-01-01', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-r', 'Reading: Fill in the Blanks',
     'Seagrass Mechanics: Structural Drag', 'In the text below some words are missing. Drag words from the box below to the appropriate place in the text. To undo an answer choice, drag the word back to the box below the text.',
     'When ocean swells roll across coastal flats, the dense foliage of seagrass beds creates friction that slows water [[b1]]. This deceleration causes particles carried in suspension to [[b2]] upon the seabed. Over successive seasons, interlaced root systems bind the deposited material into an extraordinarily [[b3]] benthic layer.', '[{"id": "A", "text": "velocity"}, {"id": "B", "text": "settle"}, {"id": "C", "text": "durable"}, {"id": "D", "text": "altitude"}, {"id": "E", "text": "evaporate"}, {"id": "F", "text": "fragile"}]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["velocity", "settle", "durable", "altitude", "evaporate", "fragile"], "correctAnswer": "velocity"}, {"id": "b2", "options": ["velocity", "settle", "durable", "altitude", "evaporate", "fragile"], "correctAnswer": "settle"}, {"id": "b3", "options": ["velocity", "settle", "durable", "altitude", "evaporate", "fragile"], "correctAnswer": "durable"}]'::jsonb,
     'Water slows its velocity (speed), particles settle (deposit), forming a durable (resilient) layer.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rfib', 1, TRUE, 120, NULL),
    ('q-pr89-rfib-01-02', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-r', 'Reading: Fill in the Blanks',
     'Seagrass Sediments: Anoxic Preservation', 'In the text below some words are missing. Drag words from the box below to the appropriate place in the text. To undo an answer choice, drag the word back to the box below the text.',
     'Carbon burial beneath seagrass beds relies upon the absence of dissolved oxygen in benthic sediments. Microbial organisms cannot easily [[b1]] complex organic compounds under completely anoxic conditions. Because this biochemical breakdown is inhibited, organic deposits remain [[b2]] over exceptionally long timescales, preventing greenhouse gas [[b3]].', '[{"id": "A", "text": "decompose"}, {"id": "B", "text": "stable"}, {"id": "C", "text": "emissions"}, {"id": "D", "text": "fertilize"}, {"id": "E", "text": "turbulent"}, {"id": "F", "text": "harvests"}]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["decompose", "stable", "emissions", "fertilize", "turbulent", "harvests"], "correctAnswer": "decompose"}, {"id": "b2", "options": ["decompose", "stable", "emissions", "fertilize", "turbulent", "harvests"], "correctAnswer": "stable"}, {"id": "b3", "options": ["decompose", "stable", "emissions", "fertilize", "turbulent", "harvests"], "correctAnswer": "emissions"}]'::jsonb,
     'Microbes decompose matter (break down), leaving deposits stable (unchanged), preventing emissions (release of gas).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rfib', 2, TRUE, 120, NULL),
    ('q-pr89-rfib-01-03', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-r', 'Reading: Fill in the Blanks',
     'Seagrass Depletion: Eutrophication Impact', 'In the text below some words are missing. Drag words from the box below to the appropriate place in the text. To undo an answer choice, drag the word back to the box below the text.',
     'Excessive nutrient runoff from coastal agriculture introduces large quantities of nitrogen into sheltered bays. These excess nutrients stimulate the rapid [[b1]] of floating phytoplankton, which dims water clarity. When light penetration becomes [[b2]], submerged seagrass leaves can no longer maintain photosynthetic [[b3]], triggering meadow decline.', '[{"id": "A", "text": "proliferation"}, {"id": "B", "text": "insufficient"}, {"id": "C", "text": "equilibrium"}, {"id": "D", "text": "extinction"}, {"id": "E", "text": "transparent"}, {"id": "F", "text": "solidification"}]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["proliferation", "insufficient", "equilibrium", "extinction", "transparent", "solidification"], "correctAnswer": "proliferation"}, {"id": "b2", "options": ["proliferation", "insufficient", "equilibrium", "extinction", "transparent", "solidification"], "correctAnswer": "insufficient"}, {"id": "b3", "options": ["proliferation", "insufficient", "equilibrium", "extinction", "transparent", "solidification"], "correctAnswer": "equilibrium"}]'::jsonb,
     'Nutrients trigger proliferation of algae (rapid growth), light becomes insufficient (too low), disrupting photosynthetic equilibrium (balance).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-001', 'g-pr89-001-rfib', 3, TRUE, 120, NULL),
    ('q-pr89-rfib-01-04', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'fill-in-blanks-r', 'Reading: Fill in the Blanks',
     'Seagrass Ecology: Megafauna Grazing', 'In the text below some words are missing. Drag words from the box below to the appropriate place in the text. To undo an answer choice, drag the word back to the box below the text.',
     'Large marine herbivores depend heavily upon healthy seagrass beds for sustenance. Animals like dugongs and green turtles [[b1]] directly upon tender shoots, digesting the carbohydrate-rich tissues. In doing so, their grazing stimulates new foliar [[b2]], which prevents older leaves from becoming excessively [[b3]] with sediment.', '[{"id": "A", "text": "forage"}, {"id": "B", "text": "growth"}, {"id": "C", "text": "encrusted"}, {"id": "D", "text": "navigate"}, {"id": "E", "text": "decay"}, {"id": "F", "text": "dissolved"}]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["forage", "growth", "encrusted", "navigate", "decay", "dissolved"], "correctAnswer": "forage"}, {"id": "b2", "options": ["forage", "growth", "encrusted", "navigate", "decay", "dissolved"], "correctAnswer": "growth"}, {"id": "b3", "options": ["forage", "growth", "encrusted", "navigate", "decay", "dissolved"], "correctAnswer": "encrusted"}]'::jsonb,
     'Herbivores forage on shoots (feed), stimulating growth (production of new shoots), preventing leaves from being encrusted (coated).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
