     NULL, '[{"id": "A", "text": "Seagrasses possess complex vascular conducting systems and genuine root structures"}, {"id": "B", "text": "Seagrasses absorb nutrients exclusively through cellular surface membranes"}, {"id": "C", "text": "Seagrasses reproduce without using underwater pollination mechanisms"}, {"id": "D", "text": "Seagrasses lack internal gas spaces for oxygen transport"}]'::jsonb, '["A"]'::jsonb, '[]'::jsonb,
     'Paragraph A states that unlike algae, seagrasses are true marine angiosperms possessing complex vascular systems, internal air spaces, and true root architectures.', 1, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
