    ('q-pr89-single-01-02', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reading-mcq-single', 'Multiple Choice, Single Answer',
     'Seagrass Metabolic Balance: Light Irradiance', 'Why do seagrasses require a higher percentage of surface incident light than most terrestrial plants (paragraph B)?',
     NULL, '[{"id": "A", "text": "Their leaves reflect the majority of blue and green light wavelengths"}, {"id": "B", "text": "Their underwater flowers require intense solar heat to open"}, {"id": "C", "text": "Their cellular membranes cannot store photosynthetic energy overnight"}, {"id": "D", "text": "Their subterranean roots in anoxic muds demand high oxygen generated through active photosynthesis"}]'::jsonb, '["D"]'::jsonb, '[]'::jsonb,
