     NULL, '[{"id": "A", "text": "Across the Eurasian steppes alongside the early domestication of horses"}, {"id": "B", "text": "Along the coastal plains of the eastern Mediterranean Levant"}, {"id": "C", "text": "In southeast Arabia, corresponding to modern Oman and the United Arab Emirates"}, {"id": "D", "text": "In the Nile Valley during the early Old Kingdom period of Egypt"}]'::jsonb, '["C"]'::jsonb, '[]'::jsonb,
