     NULL, '[{"id": "A", "text": "They were unable to transport stone blocks over water without metal barges"}, {"id": "B", "text": "They were heavily dependent on naturally sheltered bays and could only make modest coastal modifications"}, {"id": "C", "text": "They lacked timber suitable for constructing wooden merchant galleys"}, {"id": "D", "text": "Their religious customs forbade the construction of artificial stone breakwaters"}]'::jsonb, '["B"]'::jsonb, '[]'::jsonb,
