     'rp-pr89-006', 'g-pr89-006-single', 5, TRUE, 90, NULL),
    ('q-pr89-multi-06-01', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reading-mcq-multiple', 'Multiple Choice, Multiple Answers',
     'Aerodynamic Constraints: Low Reynolds Flight', 'According to paragraph A, which TWO factors characterize the physical regime of insect flight?',
     NULL, '[{"id": "A", "text": "Low Reynolds numbers where air behaves as a relatively thick, viscous fluid"}, {"id": "B", "text": "Unsteady aerodynamic conditions caused by complex oscillating wing trajectories"}, {"id": "C", "text": "Supersonic velocities that generate atmospheric sonic booms"}, {"id": "D", "text": "Steady-state laminar airflow across perfectly rigid stationary wings"}, {"id": "E", "text": "Complete absence of atmospheric air resistance at ground level"}]'::jsonb, '["A", "B"]'::jsonb, '[]'::jsonb,
