     NULL, '[{"id": "A", "text": "Ejection of microscopic water droplets to reduce insect body mass"}, {"id": "B", "text": "Sudden locking of the thoracic hinges to halt muscle oscillation"}, {"id": "C", "text": "Rapid wing rotation along the longitudinal axis generating rotational circulation lift"}, {"id": "D", "text": "Wake capture where the wing extracts kinetic energy from previously shed turbulence"}, {"id": "E", "text": "Temporary cessation of all aerodynamic forces allowing the insect to free-fall"}]'::jsonb, '["C", "D"]'::jsonb, '[]'::jsonb,
