    ('q-pr89-single-08-01', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reading-mcq-single', 'Multiple Choice, Single Answer',
     'Fossil Preservation: Amber Distinction', 'According to paragraph A, what makes amber fossils fundamentally different from typical fossilized remains?',
     NULL, '[{"id": "A", "text": "They can only be discovered inside ancient limestone cave chambers"}, {"id": "B", "text": "They preserve fragile soft-bodied organisms and delicate structures in three dimensions"}, {"id": "C", "text": "They form exclusively beneath cold abyssal oceanic sediments"}, {"id": "D", "text": "They consist of molten volcanic basalt that chilled around bones"}]'::jsonb, '["B"]'::jsonb, '[]'::jsonb,
