     NULL, '[{"id": "A", "text": "Amber dissolves rapidly whenever it comes into contact with sandstone"}, {"id": "B", "text": "Resin only captured animals that were already dead and decayed"}, {"id": "C", "text": "Fossil inclusions can only be studied if specimens are heated in acid"}, {"id": "D", "text": "Organisms that lived on or near tree trunks are disproportionately overrepresented"}]'::jsonb, '["D"]'::jsonb, '[]'::jsonb,
