    ('q-pr89-multi-08-01', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reading-mcq-multiple', 'Multiple Choice, Multiple Answers',
     'Botanical Resin: Evolutionary Function', 'According to paragraph A, which TWO functions did tree resin serve in ancient forests?',
     NULL, '[{"id": "A", "text": "Serving as an active chemical deterrent against wood-boring bark beetles"}, {"id": "B", "text": "Acting as a protective physical barrier against fungal pathogen infections"}, {"id": "C", "text": "Transporting liquid carbohydrates from roots up into leafy branches"}, {"id": "D", "text": "Attracting large predatory dinosaurs to prune lower tree limbs"}, {"id": "E", "text": "Absorbing dissolved sea salts from high-altitude rain clouds"}]'::jsonb, '["A", "B"]'::jsonb, '[]'::jsonb,
