     NULL, '[{"id": "A", "text": "Complete fossil skulls of adult Tyrannosaurus rex predators"}, {"id": "B", "text": "Subsea telecommunication cables laid across Mesozoic oceans"}, {"id": "C", "text": "Juvenile enantiornithine bird wings with preserved flight plumage"}, {"id": "D", "text": "Hematophagous tick parasites preserved grasping dinosaur feathers"}, {"id": "E", "text": "Live prehistoric bacteria that were revived in modern medical labs"}]'::jsonb, '["C", "D"]'::jsonb, '[]'::jsonb,
