     'Cable railways are finding renewed utility in hilly metropolitan areas. Urban funiculars equipped with electric motors can capture energy during downhill [[b1]]. By converting braking friction into electricity, these modern lines feed power back into municipal [[b2]], offering a clean alternative to diesel-powered bus [[b3]].', '[{"id": "A", "text": "trips"}, {"id": "B", "text": "grids"}, {"id": "C", "text": "fleets"}, {"id": "D", "text": "descents"}, {"id": "E", "text": "networks"}, {"id": "F", "text": "wagons"}]'::jsonb, '[]'::jsonb, '[{"id": "b1", "options": ["trips", "grids", "fleets", "descents", "networks", "wagons"], "correctAnswer": "trips"}, {"id": "b2", "options": ["trips", "grids", "fleets", "descents", "networks", "wagons"], "correctAnswer": "grids"}, {"id": "b3", "options": ["trips", "grids", "fleets", "descents", "networks", "wagons"], "correctAnswer": "fleets"}]'::jsonb,
     'Motors capture energy during downhill trips (journeys), feeding electricity to municipal grids (power networks), replacing bus fleets (vehicles).', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     'rp-pr89-009', 'g-pr89-009-rfib', 5, TRUE, 120, NULL),
    ('q-pr89-single-09-01', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reading-mcq-single', 'Multiple Choice, Single Answer',
