     NULL, '[{"id": "A", "text": "Frictional grip between smooth steel wheels and rails is insufficient to prevent slipping or runaway sliding"}, {"id": "B", "text": "Locomotive steam engines cannot function in cold high-altitude mountain air"}, {"id": "C", "text": "Steel tracks bend and melt under extreme atmospheric pressure on mountain peaks"}, {"id": "D", "text": "Mountain wildlife frequently damages locomotive electrical contact wires"}]'::jsonb, '["A"]'::jsonb, '[]'::jsonb,
     'Paragraph A states that standard railways operate via wheel-rail friction, and beyond gradients of 6-8%, this interface fails, causing wheel slip climbing and loss of braking adhesion descending.', 1, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
