    ('q-pr89-ro-004', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Watergate Pound Locks in Inland Waterways', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "When a vessel entered the lock, operators closed the entry gates and opened underwater sluice valves to adjust water levels inside the chamber."}, {"id": "p4", "text": "Once water levels equalized with the adjoining canal reach, the opposite gates opened to allow the barge to float smoothly onward."}, {"id": "p1", "text": "In early medieval canal networks, transport barges moving between rivers of differing elevations had to be hauled over steep, dangerous earth ramps."}, {"id": "p2", "text": "To overcome this hazard, hydraulic engineers developed the pound lock, featuring a closed rectangular chamber enclosed by two separate water gates."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
