    ('q-pr89-ro-005', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Rag Parchment Sizing in Samarkand', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "These softened rags were macerated in water-driven stamp mills, producing an exceptionally fine and homogeneous cellulose slurry."}, {"id": "p5", "text": "This starch sizing sealed the porous surface, preventing liquid calligraphy ink from bleeding and giving Samarkand paper its legendary longevity."}, {"id": "p1", "text": "In the eighth century, the Silk Road oasis city of Samarkand emerged as a renowned hub for high-grade manuscript production."}, {"id": "p4", "text": "After lifting the sheets on wire sieves, workers coated the dry paper with starch size made from fermented wheat flour."}, {"id": "p2", "text": "Local artisans refined Chinese techniques by substituting raw mulberry bark with discarded linen rags and hemp fibers."}]'::jsonb, '["p1", "p2", "p3", "p4", "p5"]'::jsonb, '[]'::jsonb,
