    ('q-pr89-ro-006', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Alpaca Fiber Grading in the Andes', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "The primary economic value of these camelids lies in their remarkably soft, hollow-core fleece, which provides superior thermal insulation."}, {"id": "p4", "text": "The finest category, baby alpaca, is reserved for luxury lightweight textiles, while coarser fibers are spun into rugged blankets and ropes."}, {"id": "p1", "text": "Indigenous pastoralist communities throughout the high Andean altiplano have raised domesticated alpacas for thousands of years."}, {"id": "p3", "text": "Following seasonal shearing, experienced sorters painstakingly grade the raw wool by hand into distinct fineness categories based on fiber diameter."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
