    ('q-pr89-ro-007', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Polynesian Double-Hulled Catamarans', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "This dual-hull architecture provided immense stability in heavy ocean swells without capsizing, allowing voyagers to transport families, livestock, and crops over thousands of nautical miles."}, {"id": "p1", "text": "Ancient Polynesian navigators colonized thousands of isolated islands across millions of square kilometres of open Pacific Ocean."}, {"id": "p2", "text": "This unprecedented maritime expansion was made possible by the development of ocean-going, double-hulled sailing canoes."}, {"id": "p3", "text": "Shipwrights connected two parallel wooden hulls with flexible lashed crossbeams, supporting a raised central deck and woven pandanus sails."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
