    ('q-pr89-ro-008', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Evolution of Baleen Whales', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Approximately thirty million years ago, a dramatic change in oceanic circulation triggered widespread upwelling of cold, nutrient-rich water."}, {"id": "p3", "text": "In response to massive blooms of krill and zooplankton, ancestral mysticetes gradually lost their teeth in favor of fibrous keratinous baleen plates."}, {"id": "p4", "text": "These comb-like filters enabled bulk filter feeding, allowing baleen whales to grow into the largest animals to have ever lived on Earth."}, {"id": "p1", "text": "Early fossil ancestors of modern baleen whales were modest-sized marine predators equipped with sharp teeth."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
