    ('q-pr89-ro-009', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Acoustics of Stradivari Violins', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Recent dendrochronological analysis revealed that Stradivari used Norway spruce harvested during the Little Ice Age, when unusually cold summers produced exceptionally narrow, uniform growth rings."}, {"id": "p4", "text": "This uniform wood density, combined with chemical mineral soaks containing alum and borax, created an ultralight acoustic soundboard that vibrates with peerless clarity."}, {"id": "p1", "text": "Violins crafted in seventeenth-century Cremona by Antonio Stradivari are renowned for their extraordinary tonal depth and projection."}, {"id": "p2", "text": "For centuries, luthiers and physicists debated whether this legendary acoustic quality stemmed from secret varnishes or instrument geometry."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
