    ('q-pr89-ro-010', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Traditional Windcatchers in Desert Architecture', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "These architectural towers rose high above rooftop levels to catch faster, cooler breezes blowing across the upper atmosphere."}, {"id": "p1", "text": "Settlements built across the arid deserts of the Middle East faced extreme daytime temperatures without modern electrical cooling."}, {"id": "p4", "text": "Internal vertical baffles funneled this fresh air downward through basement water pools, cooling and humidifying the air before releasing it into living rooms."}, {"id": "p2", "text": "To maintain comfortable indoor conditions, vernacular architects incorporated tall vertical ventilation towers known as windcatchers."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
