    ('q-pr89-ro-011', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Archaeology of Mohenjo-Daro Drains', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "A defining feature of sites like Mohenjo-Daro was a sophisticated city-wide network of covered sanitary drains."}, {"id": "p4", "text": "These public drains were covered with removable flat limestone slabs, allowing municipal maintenance workers to clear accumulated silt and avoid urban contamination."}, {"id": "p1", "text": "The Bronze Age cities of the Indus Valley Civilisation, dating to roughly 2500 BCE, exhibited unmatched municipal town planning."}, {"id": "p3", "text": "Individual domestic bathrooms channeled wastewater into baked-brick conduits running along the centers of major streets."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
