    ('q-pr89-ro-012', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Parchment Preparation from Untanned Hides', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "While stretched under tension, artisans shaved the skin with a crescent-shaped lunellum knife to produce a smooth, velvet writing surface."}, {"id": "p1", "text": "Before paper manufacturing spread across Europe, medieval scribes transcribed manuscripts onto parchment prepared from untanned animal hides."}, {"id": "p2", "text": "Tanners first soaked raw pelts in vats of slaked lime solution for several days to dissolve natural fats and loosen hair follicles."}, {"id": "p3", "text": "Workers then scraped the dehaired skins clean and stretched them taut across circular wooden frames called herse."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-012'),
    ('q-pr89-ro-013', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Physics of Curling Stones', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Unlike ordinary objects sliding on friction, a rotating curling stone curls in the same direction as its rotational spin."}, {"id": "p3", "text": "To manipulate this curved trajectory, teammates vigorously sweep the pebbled ice directly in front of the moving stone with broom heads."}, {"id": "p4", "text": "This friction temporarily melts a microscopic thin film of liquid water, reducing drag and extending the stone''s distance and steering line."}, {"id": "p1", "text": "In the winter sport of curling, players slide polished granite stones across a prepared sheet of ice toward a target circular house."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-013'),
    ('q-pr89-ro-014', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Viking Sunstone Polarisation Navigation', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Historical sagas recount that Norse navigators relied on optical crystals known as solarsteinn (sunstones) to find their bearings when the sun was hidden."}, {"id": "p4", "text": "Modern optical experiments confirmed that transparent crystals of Iceland spar (calcite) polarize diffuse daylight, allowing navigators to pinpoint the sun''s exact celestial position behind heavy clouds."}, {"id": "p1", "text": "Early medieval Norse seafarers crossed thousands of kilometres of open ocean between Scandinavia, Iceland, and Greenland."}, {"id": "p2", "text": "Navigating across these high-latitude seas was fraught with peril due to frequent overcast skies, dense fog, and prolonged polar twilights."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-014'),
    ('q-pr89-ro-015', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Ancient Olive Pressing Beam Presses', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "The resulting mash was scooped into woven hemp baskets and stacked beneath colossal wooden lever beams weighted with stone counterweights."}, {"id": "p1", "text": "Olive oil was an indispensable agricultural staple across the ancient Mediterranean, used for cooking, lighting, and religious rituals."}, {"id": "p4", "text": "As the lever pressed downward, virgin oil and dark bitter water filtered through the weave into settling vats, where pure oil was skimmed from the surface."}, {"id": "p2", "text": "Harvested olives were initially crushed in large circular stone basins (the trapetum) to break the fruit pulp without shattering the bitter inner pits."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-015'),
    ('q-pr89-ro-016', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Mechanics of Woodpecker Skulls', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Biomechanical engineers investigated how these birds routinely survive such violent impacts without suffering concussions or brain trauma."}, {"id": "p4", "text": "Furthermore, an elongated hyoid bone wraps completely around the skull like a natural safety harness, damping vibrations before they can reach delicate brain tissues."}, {"id": "p1", "text": "Woodpeckers repeatedly hammer their beaks into solid tree trunks with deceleration forces exceeding one thousand times the force of gravity."}, {"id": "p3", "text": "Micro-CT imaging revealed that the bird''s brain is tightly encased within dense, spongy cranial bone that disperses mechanical shockwaves."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
