    ('q-pr89-ro-017', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Crucible Smelting of Ancient Wootz Blades', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "When slowly cooled over days, the steel precipitated micro-bands of hard iron carbides that produced the wavy watered patterns characteristic of historical Damascus swords."}, {"id": "p1", "text": "During the first millennium BCE, metallurgists in southern India developed Wootz, an ultra-high-carbon crucible steel of legendary strength."}, {"id": "p2", "text": "Smiths sealed porous iron ore, dry wood chips, and plant leaves inside airtight refractory clay crucibles before placing them in high-heat charcoal furnaces."}, {"id": "p3", "text": "The burning vegetation emitted carbon monoxide that rapidly infused into the molten iron, raising its carbon content to roughly 1.5 percent."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-017'),
    ('q-pr89-ro-018', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Venetian Glass Blowing Guilds', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "In 1291, Venetian authorities enacted a strict decree ordering all glassmaking furnaces to be relocated to the isolated island of Murano."}, {"id": "p3", "text": "While officially framed as a fire-prevention measure for the wooden city, the relocation primarily served to safeguard secret chemical recipes from rival European nations."}, {"id": "p4", "text": "Glassblowers on Murano were forbidden from leaving the republic under penalty of death, preserving a Venetian commercial monopoly that endured for centuries."}, {"id": "p1", "text": "During the Middle Ages, the Republic of Venice dominated the European trade in luxury glassware and mirror manufacture."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
