    ('q-pr89-ro-019', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Architecture of Stepwell Wells', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "These structures incorporated descending flights of stone stairs flanked by multi-tiered carved pavilions that reached deep subterranean water tables."}, {"id": "p4", "text": "As the water table fluctuated between seasons, residents could descend to whatever depth the water stood, while the shaded masonry provided a cool communal sanctuary from the desert heat."}, {"id": "p1", "text": "In the semi-arid states of western India, monsoonal rainfall is intensely seasonal, followed by months of acute scorching drought."}, {"id": "p2", "text": "To secure dependable water supplies throughout the dry season, medieval kingdoms engineered monumental subterranean stepwells known as baolis."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-019'),
    ('q-pr89-ro-020', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Cold Storage Icehouses in Historic Estates', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "During freezing winter months, estate laborers harvested thick ice blocks from frozen ornamental ponds and packed them into the underground chambers."}, {"id": "p1", "text": "Before the advent of mechanical refrigeration, maintaining fresh dairy, meat, and vegetables during hot summer months was a major domestic challenge."}, {"id": "p4", "text": "Insulated with thick layers of dry straw and heavy timber doors, these subterranean storage vaults kept ice frozen throughout the following summer."}, {"id": "p2", "text": "Estate owners resolved this difficulty by constructing deep subterranean icehouses sheltered beneath wooded hillsides."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-020'),
    ('q-pr89-ro-021', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Enzymatic Digestion in Carnivorous Flora', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Carnivorous pitcher plants overcame this environmental barrier by evolving modified cup-shaped leaves that trap unwary insects."}, {"id": "p4", "text": "Potent proteolytic enzymes then dissolve the prey''s soft tissues, allowing the plant to absorb vital nitrogen compounds directly through its foliage."}, {"id": "p1", "text": "In nutrient-deficient habitats like waterlogged bogs, standard plants struggle to absorb essential nitrogen and phosphorus from the soil."}, {"id": "p3", "text": "Insects slipping into the pitcher drown in an acidic pool of digestive fluid secreted by specialized glandular cells lining the interior walls."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-021'),
    ('q-pr89-ro-022', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Ancient Roman Milestones and Surveying', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "These markers enabled imperial couriers and military legions to calculate journey times and coordinate logistical movements across vast continental distances."}, {"id": "p1", "text": "The administrative cohesion of the Roman Empire was anchored by an expansive highway network extending over eighty thousand kilometres."}, {"id": "p2", "text": "To map and regulate transit along these arteries, surveyors (agrimensores) erected cylindrical stone milestones at intervals of precisely one Roman mile."}, {"id": "p3", "text": "Each carved pillar indicated the distance to Rome or the nearest provincial capital, alongside the name of the emperor who funded the road''s construction."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-022'),
    ('q-pr89-ro-023', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Aerodynamics of Maple Seed Whirlybirds', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Instead of falling straight to the forest floor, the asymmetrical seed auto-rotates rapidly around its center of gravity like a miniature helicopter."}, {"id": "p3", "text": "This continuous spinning creates a stable leading-edge vortex above the winglet, dramatically increasing aerodynamic lift."}, {"id": "p4", "text": "By drastically slowing its descent velocity, the spinning samara allows passing wind currents to carry the seedling far away from the shade of the parent tree."}, {"id": "p1", "text": "In autumn, mature maple trees shed winged aerodynamic seed pods known to botanists as samaras."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-023'),
    ('q-pr89-ro-024', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Bronze Age Tin Mining in Cornwall', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "In Cornwall, miners extracted heavy black cassiterite pebbles from alluvial stream gravels using panning and trenching techniques."}, {"id": "p4", "text": "The smelted tin ingots were then shipped across the English Channel and transported across Europe, sustaining the continent''s Bronze Age economy."}, {"id": "p1", "text": "During the Bronze Age, metallurgical production required alloying soft copper with approximately ten percent tin to forge durable weapons and tools."}, {"id": "p2", "text": "Because geological tin deposits are exceptionally rare in the Mediterranean, ancient smiths relied on long-distance maritime trade routes to southwestern Britain."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-024'),
    ('q-pr89-ro-025', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Optics of Camera Obscura', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "This geometric intersection projects an inverted and reversed color image of the illuminated exterior scene onto the opposing wall."}, {"id": "p1", "text": "The foundational optical principle behind modern photography was observed in antiquity: the camera obscura."}, {"id": "p4", "text": "By the Renaissance, artists like Leonardo da Vinci and Johannes Vermeer utilized portable camera obscura boxes fitted with glass lenses to trace perspectives with lifelike accuracy."}, {"id": "p2", "text": "When sunlight passes through a tiny pinhole into a completely darkened chamber, light rays traveling in straight paths cross at the aperture."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-025'),
    ('q-pr89-ro-026', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Tungsten Filament Incandescent Bulbs', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "In 1904, Hungarian and American chemists sought a more resilient alternative with a higher melting point to prevent filament evaporation."}, {"id": "p4", "text": "When encased within glass bulbs filled with inert argon gas rather than a vacuum, coiled tungsten filaments delivered thousands of hours of reliable illumination."}, {"id": "p1", "text": "Early electric incandescent light bulbs relied on carbonized bamboo or cellulose filaments that burned out after a few hundred hours."}, {"id": "p3", "text": "They turned to metallic tungsten, an element capable of operating at white-hot temperatures exceeding 2,500 degrees Celsius without melting."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-026'),
    ('q-pr89-ro-027', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Physiology of Deep Diving Seals', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "Simultaneously, peripheral blood vessels constrict, shutting off blood flow to muscles and skin to prioritize oxygen delivery exclusively to the brain and heart."}, {"id": "p1", "text": "Weddell seals in Antarctica routinely dive to depths exceeding six hundred metres in search of fish, remaining submerged for over an hour."}, {"id": "p2", "text": "To achieve these extraordinary dives on a single breath, the seals rely on extreme physiological adaptations that minimize oxygen consumption."}, {"id": "p3", "text": "Upon descending, an involuntary mammalian dive reflex abruptly slows their heart rate from eighty beats per minute to fewer than fifteen."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-027'),
    ('q-pr89-ro-028', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Navigation of Dung Beetles by Starlight', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Rolling in an erratic circle risks returning to the mound, where aggressive rivals will steal the hard-earned food ball."}, {"id": "p3", "text": "Behavioral experiments conducted in South African planetariums demonstrated that nocturnal beetles climb atop their ball and perform an orientation dance."}, {"id": "p4", "text": "By referencing the diffuse polarization of the Milky Way across the night sky, the beetles maintain flawless straight courses even on moonless nights."}, {"id": "p1", "text": "After fashioning a fresh ball of herbivore dung, African dung beetles must roll it away from crowded communal mounds in a straight line."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-028'),
    ('q-pr89-ro-029', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Submerged Bog Oak Wood Mineralization', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Over millennia, acidic, oxygen-starved bog water dissolved iron salts, which reacted chemically with natural tannins in the oak wood."}, {"id": "p4", "text": "This geochemical reaction transformed the timber into bog oak, a lustrous jet-black semi-fossilized hardwood prized by cabinetmakers for fine furniture."}, {"id": "p1", "text": "Thousands of years ago, vast primeval oak forests grew across the lowland basins of the British Isles and northern Europe."}, {"id": "p2", "text": "As regional climates became wetter, rising water tables submerged the trees, which fell and became buried in anaerobic peat bogs."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-029'),
    ('q-pr89-ro-030', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Waxed Linen Cartography in Mediterranean Navigation', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Draughtsmen coated the woven linen backing with bees wax and natural resins to make the maps impervious to saltwater spray."}, {"id": "p1", "text": "During the late Middle Ages, maritime merchants expanding Mediterranean trade routes required precise navigational maps that could withstand damp sea air."}, {"id": "p4", "text": "Using magnetic compass directions, they inked radiating network lines across the water-resistant charts, enabling navigators to plot reliable open-sea bearings."}, {"id": "p2", "text": "Italian and Catalan cartographers developed portolan charts drawn on durable animal vellum and treated linen cloth."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-030'),
    ('q-pr89-ro-031', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Domestication of Maize in Oaxaca', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Teosinte bore only tiny spikes containing five to ten hard, triangular kernels encased in impenetrable stony fruit cases."}, {"id": "p4", "text": "Centuries of systematic selective breeding gradually transformed this modest wild grass into modern corn with hundreds of soft, exposed grains on a central cob."}, {"id": "p1", "text": "The wild ancestor of modern domesticated maize is teosinte, a wild grass native to the Balsas River valley of southwestern Mexico."}, {"id": "p3", "text": "Approximately nine thousand years ago, indigenous foragers in Oaxaca began selectively cultivating plants that displayed rare genetic mutations that prevented kernel casing formation."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-031'),
    ('q-pr89-ro-032', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Engineering of Medieval Catapults', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "When released, the heavy counterweight fell rapidly, swinging the long throwing arm and slinging stone boulders weighing over one hundred kilograms across hundreds of metres."}, {"id": "p1", "text": "In medieval siege warfare, attacking forces required heavy artillery capable of breaching thick stone castle curtain walls."}, {"id": "p2", "text": "By the twelfth century, military engineers developed the counterweight trebuchet, an immense gravity-powered throwing machine."}, {"id": "p3", "text": "The machine operated on the principle of a seesaw lever: a massive box filled with dozens of tonnes of stones was raised on the short arm."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-032'),
    ('q-pr89-ro-033', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Ancient Mayan Cenote Sinkholes', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "To support large urban populations, ancient Maya city-states relied entirely on cenotes—colossal natural sinkholes formed by collapsed cave ceilings."}, {"id": "p3", "text": "These circular vertical shafts punctured the porous limestone bedrock, exposing deep, subterranean groundwater aquifers filled with crystalline rainwater."}, {"id": "p4", "text": "Major urban centers like Chichen Itza were built directly around these life-sustaining sinkholes, which served both as municipal water reservoirs and as sacred portals for religious offerings."}, {"id": "p1", "text": "The limestone plateau of the Yucatan Peninsula in southern Mexico possesses virtually no surface rivers, streams, or freshwater lakes."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-033'),
    ('q-pr89-ro-034', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Traditional Terracotta Roof Tile Manufacturing', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "The prepared clay was pressed into curved wooden molds to form distinctive semi-cylindrical pan and cover tiles."}, {"id": "p4", "text": "After drying slowly on shaded wooden racks to prevent shrinkage cracks, the tiles were fired in wood kilns until the minerals fused into waterproof terracotta."}, {"id": "p1", "text": "Throughout the Mediterranean basin, building durable roofs that could withstand intense sun and winter rain required ceramic roofing materials."}, {"id": "p2", "text": "Artisans began the manufacturing process by excavating local alluvial clays and kneading the raw earth with water in foot-treading pits."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
