    ('q-pr89-ro-035', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Aerodynamics of Hummingbird Hovering', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Their ball-and-socket shoulder joints allow them to swivel their rigid wings upside down at the stroke reversal point in a continuous horizontal figure-eight motion."}, {"id": "p1", "text": "Hummingbirds are the only avian species capable of sustained, stationary hovering and sustained backwards flight."}, {"id": "p4", "text": "This symmetrical bilateral flapping pattern generates steady upward aerodynamic support that keeps the tiny bird perfectly motionless while sipping floral nectar."}, {"id": "p2", "text": "Unlike other birds, which produce aerodynamic lift almost exclusively during the downward wingbeat, hummingbirds generate lift on both strokes."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-035'),
    ('q-pr89-ro-036', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Seismology of Deep Moonquakes', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "These instruments detected thousands of deep moonquakes originating between eight hundred and one thousand kilometres beneath the lunar crust."}, {"id": "p4", "text": "Gravitational tidal forces exerted by Earth cyclically squeeze and deform the lunar mantle, proving that celestial tides can trigger internal fracturing on extraterrestrial bodies."}, {"id": "p1", "text": "Between 1969 and 1972, Apollo astronauts deployed a network of passive seismometers across the lunar surface to record vibrations."}, {"id": "p3", "text": "Analysis of the recorded wave signatures revealed that these tremors occur on a regular monthly cycle matching the Moon''s eccentric orbit around Earth."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-036'),
    ('q-pr89-ro-037', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Traditional Felt Production from Sheep Wool', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "Artisans then rolled the wet mats around wooden poles and rhythmically pressed them for hours, causing the scales to interlock permanently into warm, windproof fabric."}, {"id": "p1", "text": "Felt is widely recognized by anthropologists as humanity''s earliest fabricated textile, predating spinning wheels and woven cloth."}, {"id": "p2", "text": "Pastoral nomadic artisans produced dense felt sheets by shearing raw wool fleece and carding the tangled fibers into broad, layered mats."}, {"id": "p3", "text": "These layered wool mats were thoroughly saturated with hot water and alkaline soap to relax the microscopic scales along each fiber shaft."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-037'),
    ('q-pr89-ro-038', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Ancient Qanat Subterranean Irrigation Channels', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Miners first sank a vertical mother well deep into an alluvial fan at the foothills until tapping the subterranean water table."}, {"id": "p3", "text": "From this source, diggers excavated a gently sloping underground tunnel extending miles toward lowland agricultural fields."}, {"id": "p4", "text": "Vertical shafts were spaced along the tunnel route to provide ventilation and allow workers to haul out excavated soil and debris."}, {"id": "p1", "text": "In the arid plateaus of ancient Persia, communities developed qanats to transport mountain groundwater across vast desert distances."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-038'),
    ('q-pr89-ro-039', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Evolution of Geckos Climbing Pads', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Electron microscopy revealed that gecko toe pads are covered with millions of microscopic keratinous hairs called setae, which branch into billions of spatulae."}, {"id": "p4", "text": "When these nanoscale spatulae come into intimate contact with a surface, weak intermolecular van der Waals forces produce immense collective adhesion without leaving sticky residues."}, {"id": "p1", "text": "Geckos possess an astounding ability to scurry up vertical glass panes and run effortlessly across polished ceilings upside down."}, {"id": "p2", "text": "For decades, zoologists assumed their adhesion relied on chemical glues, suction cups, or microscopic mechanical claws."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-039'),
    ('q-pr89-ro-040', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Structural Mechanics of Gothic Vaults', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Pointed arches channeled the vertical dead weight of the stone ceiling directly downward into slender clustered columns rather than outward against exterior walls."}, {"id": "p1", "text": "Romanesque churches of the early Middle Ages were characterized by thick, monolithic stone walls with few windows to support massive barrel vaults."}, {"id": "p4", "text": "By adding exterior flying buttresses to absorb residual lateral thrust, architects could replace heavy masonry walls with soaring expanses of stained glass."}, {"id": "p2", "text": "In the twelfth century, French master masons pioneered ribbed groin vaulting combined with pointed arches to overcome this structural confinement."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-040'),
    ('q-pr89-ro-041', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Stratified Soil Trenching in Historical Archaeology', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Archaeologists begin by laying out a precision metric grid across the site and digging vertical exploratory trenches."}, {"id": "p4", "text": "By recording the precise three-dimensional coordinate of every discovered pottery sherd and stone tool within these layers, researchers reconstruct the timeline of human activity."}, {"id": "p1", "text": "Uncovering the chronological sequence of human occupation at an ancient settlement requires meticulous stratigraphical excavation."}, {"id": "p3", "text": "As excavators peel back successive layers of earth, distinct soil strata representing different cultural eras become visible in the trench walls."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-041'),
    ('q-pr89-ro-042', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Ecology of Epiphytic Bromeliads', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "Specialized tree frogs, aquatic insects, and crabs spend their entire life cycles inside these treetop pools, while the bromeliad absorbs nutrients directly through foliar trichomes."}, {"id": "p1", "text": "In the dense canopies of tropical rainforests, ground-level sunlight is severely limited, prompting plants to seek alternative habitats high on tree branches."}, {"id": "p2", "text": "Epiphytic bromeliads evolved a specialized aerial architecture: tightly overlapping leaf bases that form an impermeable central water cistern."}, {"id": "p3", "text": "These aerial phytotelmata capture rainfall, falling leaf detritus, and insect droppings, creating suspended aquatic micro-ecosystems high in the canopy."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-042'),
    ('q-pr89-ro-043', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Physics of Boomerang Returning Flight', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "The weapon''s ability to fly in an enormous circular arc and return to the thrower depends on two intersecting aerodynamic principles."}, {"id": "p3", "text": "Each wing of the boomerang is sculpted into an asymmetric aerofoil; as it spins horizontally through the air, the forward-sweeping wing generates more lift than the retreating wing."}, {"id": "p4", "text": "This lift imbalance exerts an uneven aerodynamic torque that induces gyroscopic precession, causing the spinning trajectory to curve continuously until it returns to its origin point."}, {"id": "p1", "text": "Aboriginal Australians invented the returning boomerang thousands of years ago, crafting it from curved hardwood branches for hunting and ceremonial use."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-043'),
    ('q-pr89-ro-044', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Ancient Egyptian Faience Glazing', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "As the shaped objects dried in the hot Egyptian sun, soluble copper and natron salts effloresced to the exterior surface, forming a powdery white crust."}, {"id": "p4", "text": "When fired in wood kilns, this mineral crust melted into a self-glazing, brilliant blue vitreous coating that permanently sealed the porous quartz core."}, {"id": "p1", "text": "In ancient Egypt, craftspeople produced faience—a non-clay ceramic material with a bright, glassy turquoise sheen prized as a synthetic alternative to turquoise stone."}, {"id": "p2", "text": "The raw body paste was prepared by mixing crushed quartz sand, alkaline natron salts, copper oxide colorant, and lime with water into shaped figurines."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-044'),
    ('q-pr89-ro-045', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Navigation of Sea Turtles by Geomagnetism', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Biologists placed young turtles inside controlled magnetic coils, altering the local magnetic inclination and field intensity."}, {"id": "p1", "text": "Newly hatched loggerhead sea turtles emerge from coastal beach nests and embark on multi-year transoceanic migrations across open seas."}, {"id": "p4", "text": "The turtles systematically reoriented their swimming direction in response to the artificial fields, proving they possess an innate internal magnetic map that guides their trans-oceanic navigation."}, {"id": "p2", "text": "Despite crossing thousands of miles of featureless ocean without visual landmarks, juvenile turtles maintain precise navigational headings."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-045'),
    ('q-pr89-ro-046', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Metallurgy of Ancient Platinum in Ecuador', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Working with platinum presented an immense technological hurdle: its melting point of 1,768 degrees Celsius far exceeded the heat capability of charcoal blowpipe furnaces."}, {"id": "p4", "text": "The molten gold flowed around the platinum granules, binding them into an alloy that could be repeatedly heated, hammered, and polished into gleaming masks and ornaments."}, {"id": "p1", "text": "In pre-Columbian South America, indigenous metallurgists of the La Tolita culture crafted ceremonial jewelry from platinum centuries before European scientists knew the metal existed."}, {"id": "p3", "text": "La Tolita smiths devised a powder metallurgy technique known as sintering: mixing fine platinum grains with low-melting gold dust on a charcoal hearth."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-046'),
    ('q-pr89-ro-047', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Evolution of Penguin Feathers', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p4", "text": "This dense arrangement traps a permanent layer of warm air next to the skin, preventing cold seawater from breaching the thermal barrier during deep fishing dives."}, {"id": "p1", "text": "Unlike flighted birds whose feathers are arranged along distinct linear tracts with bare skin beneath, penguins possess a completely uniform, continuous feather coat."}, {"id": "p2", "text": "This specialized plumage is an evolutionary adaptation for enduring continuous submersion in freezing sub-Antarctic waters."}, {"id": "p3", "text": "Each feather is short, stiff, and densely packed, featuring an oily waterproof outer barb and a downy, insulating underlayer."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-047'),
    ('q-pr89-ro-048', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Chemistry of Ancient Birch Pitch Glue', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p2", "text": "Extracting pitch from white birch bark required an exacting pyrotechnic process called anoxic dry distillation."}, {"id": "p3", "text": "Neanderthals rolled sheets of bark inside sealed earthen pits beneath charcoal fires, heating the material to roughly four hundred degrees Celsius in the complete absence of oxygen."}, {"id": "p4", "text": "The heating vaporized complex betulin resins, which condensed into a dark, pliable tar that Neanderthals used to haft stone spear points securely onto wooden shafts."}, {"id": "p1", "text": "In the Middle Paleolithic era, Neanderthals produced birch bark pitch, widely recognized as humanity''s earliest manufactured synthetic adhesive."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
     'Correct sequential order: p1 -> p2 -> p3 -> p4. Restores the original narrative cohesion.', 3, 'medium', ARRAY['PTE Reading', 'Original practice', 'Batch D'],
     NULL, NULL, 0, TRUE, 150, 'ri-pr89-ro-048'),
    ('q-pr89-ro-049', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'Clepsydra Outflow Clocks in Ancient Greece', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Before an orator began their legal address, court attendants filled the container with a measured volume of water and unstopped the nozzle."}, {"id": "p4", "text": "As liquid drained steadily through the orifice, the descending surface line marked equal increments of elapsed time on internal scale rings."}, {"id": "p1", "text": "To regulate speaking times in Athenian law courts, ancient Greeks relied on the clepsydra, a calibrated outflow clock."}, {"id": "p2", "text": "The device consisted of a cylindrical stone vessel fitted with a pierced bronze outflow nozzle near its base."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
