    ('q-pr89-ro-050', 'pte-2026-01', 'PTE', ARRAY['PTE'], 'reading', 'reorder-paragraphs', 'Re-order Paragraphs',
     'The Braiding of Incan Suspension Cables', 'The text boxes below have been placed in a random order. Restore the original order.',
     NULL, '[{"id": "p3", "text": "Local communities harvested tough mountain grass, braided it into small cords, and twisted these cords into massive cables as thick as a human torso."}, {"id": "p1", "text": "The rugged topography of the Andes Mountains presented immense geographic barriers to transit within the Inca Empire."}, {"id": "p4", "text": "Anchored into solid stone abutments on opposite canyon rims, these woven grass cables supported foot bridges that carried imperial couriers and llama caravans safely across alpine gorges."}, {"id": "p2", "text": "To span yawning river chasms where wooden timber or stone arches were impossible, Incan engineers developed suspension spans woven entirely from wild ichu grass."}]'::jsonb, '["p1", "p2", "p3", "p4"]'::jsonb, '[]'::jsonb,
